using Coplt.Mathematics;
using static Coplt.Mathematics.math;

namespace Tests.Scalar;

/// <summary>
/// The functions of the scalar types. Every numeric type has the functions of the <c>math</c> class and the
/// members that are called on a value, which are the members of <c>ScalarExtensions</c>, they are generated by
/// the source generator.
/// </summary>
public class TestScalarMath
{
    /// <summary>
    /// The estimate of the hardware is not exact, the one of the arm platform is the loose one of the two, so the
    /// tolerance leaves room for it.
    /// </summary>
    private const float Tolerance = 0.01f;

    /// <inheritdoc cref="Tolerance"/>
    private const double DoubleTolerance = 0.01;

    [Test]
    public void Arithmetic()
    {
        Assert.That(min(3, 5), Is.EqualTo(3));
        Assert.That(max(3, 5), Is.EqualTo(5));
        Assert.That(clamp(7, 1, 5), Is.EqualTo(5));
        Assert.That(clamp(0, 1, 5), Is.EqualTo(1));
        // the lower bound of the range is asked before the upper one, so the bounds over one another place the
        // value at the upper bound of the two instead of raising the exception of the member of the BCL
        Assert.That(clamp(5, 10, 0), Is.EqualTo(0));
        Assert.That(abs(-4), Is.EqualTo(4));
        Assert.That(sign(-4), Is.EqualTo(-1));
        Assert.That(sign(4), Is.EqualTo(1));
        Assert.That(sign(0), Is.EqualTo(0));
        Assert.That(square(3), Is.EqualTo(9));
        Assert.That(dot(3, 4), Is.EqualTo(12));
        Assert.That(fma(2, 3, 4), Is.EqualTo(10));
        Assert.That(fms(2, 3, 4), Is.EqualTo(2));
        Assert.That(fnma(2, 3, 4), Is.EqualTo(-2));
        Assert.That(lerp(0, 10, 1), Is.EqualTo(10));
        Assert.That(unlerp(5, 0, 10), Is.EqualTo(0));
        Assert.That(remap(3, 0, 3, 0, 9), Is.EqualTo(9));
        Assert.That(length_sq(-3), Is.EqualTo(9));
        Assert.That(distance_sq(2, 5), Is.EqualTo(9));
        // the minimum and the maximum of the platform are the ones of the values of their own: a kind that has
        // neither a value that is not a number nor a negative zero has no such difference
        Assert.That(min_native(3, 5), Is.EqualTo(3));
        Assert.That(max_native(3, 5), Is.EqualTo(5));
        // every reduction of a value of one component is the whole of the value
        Assert.That(sum(3), Is.EqualTo(3));
        Assert.That(hmin(3), Is.EqualTo(3));
        Assert.That(hmax(3), Is.EqualTo(3));
        Assert.That(hmin_native(3), Is.EqualTo(3));
        Assert.That(hmax_native(3), Is.EqualTo(3));
    }

    [Test]
    public void EveryIntegerType()
    {
        Assert.That(min(3u, 5u), Is.EqualTo(3u));
        Assert.That(abs(-4L), Is.EqualTo(4L));
        // the absolute value of the smallest value of a signed kind is not a value of the kind: the negation of
        // the value of the kind wraps into the value itself, which the member answers instead of raising
        Assert.That(abs(short.MinValue), Is.EqualTo(short.MinValue));
        Assert.That(abs(int.MinValue), Is.EqualTo(int.MinValue));
        Assert.That(abs(long.MinValue), Is.EqualTo(long.MinValue));
        Assert.That(clamp(long.MinValue, 10L, 0L), Is.EqualTo(0L));
        Assert.That(sign(4ul), Is.EqualTo(1ul));
        Assert.That(square((short)-3), Is.EqualTo((short)9));
        Assert.That(dot((ushort)3, (ushort)4), Is.EqualTo((ushort)12));
        Assert.That(distance_sq((short)2, (short)5), Is.EqualTo((short)9));
        Assert.That(up2_pow2((ushort)5), Is.EqualTo((ushort)8));
    }

    [Test]
    public void FloatingPoint()
    {
        Assert.That(ceil(1.2f), Is.EqualTo(2f));
        Assert.That(floor(1.8f), Is.EqualTo(1f));
        Assert.That(round(1.5f), Is.EqualTo(2f));
        Assert.That(round(2.5f), Is.EqualTo(2f));
        Assert.That(round_away(1.5f), Is.EqualTo(2f));
        Assert.That(round_away(2.5f), Is.EqualTo(3f));
        Assert.That(round_away(-2.5f), Is.EqualTo(-3f));
        Assert.That(trunc(-1.8f), Is.EqualTo(-1f));
        Assert.That(frac(-1.25f), Is.EqualTo(0.75f));
        Assert.That(fmod(-1f, 3f), Is.EqualTo(2f));
        // the product of the remainder is fused, so the subtraction of it is exact
        Assert.That(fmod(1f, 0.1f), Is.EqualTo(-1.4901161193847656E-08f));
        Assert.That(rcp(4f), Is.EqualTo(0.25f));
        Assert.That(saturate(2f), Is.EqualTo(1f));
        // the sign of a value that is not a number is the one of the bit of the sign of it, the BCL throws for
        // one of those, and the one of the kind of the library has the bit of the sign set
        var positiveNaN = BitConverter.UInt32BitsToSingle(BitConverter.SingleToUInt32Bits(float.NaN) & 0x7FFFFFFFu);
        Assert.That(sign(float.NaN), Is.EqualTo(-1f), "the not a number of the kind");
        Assert.That(sign(positiveNaN), Is.EqualTo(1f), "the not a number of the kind that is turned around");
        Assert.That(sign(double.NaN), Is.EqualTo(-1d), "the not a number of a double");
        Assert.That(chg_sign(2f, -1f), Is.EqualTo(-2f));
        Assert.That(chg_sign(-2f, 1f), Is.EqualTo(-2f));
        Assert.That(chg_sign(2f, float.NaN), Is.EqualTo(-2f), "the sign of the not a number of the kind");
        Assert.That(chg_sign(2f, positiveNaN), Is.EqualTo(2f), "the sign of the not a number that is turned around");
        Assert.That(chg_sign(2d, -1d), Is.EqualTo(-2d));
        Assert.That(chg_sign((Half)2f, (Half)(-1f)), Is.EqualTo((Half)(-2f)));
        // the sign of a negative zero is turned around like the one of every other value
        Assert.That(BitConverter.SingleToInt32Bits(chg_sign(2f, -0f)),
            Is.EqualTo(BitConverter.SingleToInt32Bits(-2f)), "the negative zero");
        Assert.That(copy_sign(2f, -1f), Is.EqualTo(-2f));
        Assert.That(copy_sign(-2f, 1f), Is.EqualTo(2f));
        Assert.That(copy_sign(2f, -0f), Is.EqualTo(-2f), "the sign of the negative zero");
        Assert.That(copy_sign(2d, 1d), Is.EqualTo(2d));
        Assert.That(copy_sign((Half)2f, (Half)(-1f)), Is.EqualTo((Half)(-2f)));
        Assert.That(step(2f, 3f), Is.EqualTo(1f));
        Assert.That(step(3f, 2f), Is.EqualTo(0f));
        Assert.That(smoothstep(0f, 1f, 0.5f), Is.EqualTo(0.5f));
        Assert.That(reflect(1f, 1f), Is.EqualTo(-1f));
        Assert.That(project(2f, 1f), Is.EqualTo(2f));
        // a value to project onto that is too short to be projected onto answers with the zero of its kind
        Assert.That(project(2f, 0f), Is.EqualTo(0f));
        Assert.That(project(2f, 1e-9f), Is.EqualTo(0f), "the denom epsilon of the kind");
        Assert.That(project_unsafe(2f, 1f), Is.EqualTo(2f));
        Assert.That(project_unsafe(2f, 0f), Is.NaN);
        Assert.That(project_unit(2f, 1f), Is.EqualTo(2f));
        Assert.That(project_on_plane(2f, 1f), Is.EqualTo(0f));
        Assert.That(project_on_plane_unit(2f, 1f), Is.EqualTo(0f));
        Assert.That(project_safe(2f, 0f), Is.EqualTo(0f));
        Assert.That(face_forward(1f, 1f, 1f), Is.EqualTo(-1f));
        Assert.That(face_forward(1f, 1f, -1f), Is.EqualTo(1f));
        Assert.That(wrap(4f, 0f, 3f), Is.EqualTo(1f));
        Assert.That(wrap(-1f, 0f, 3f), Is.EqualTo(2f));
        Assert.That(length(-3f), Is.EqualTo(3f));
        Assert.That(distance(2f, 5f), Is.EqualTo(3f));
        Assert.That(normalize(2f), Is.EqualTo(1f));
        Assert.That(normalize_safe(0f), Is.EqualTo(0f));
        // the length of a value that is too short to be squared is zero, which is below the smallest positive
        // normal value of the kind of it
        Assert.That(normalize_safe(float.Epsilon), Is.EqualTo(0f));
        Assert.That(normalize_safe(1e-30f), Is.EqualTo(0f));
        Assert.That(normalize_safe(1e-320d), Is.EqualTo(0d));
        Assert.That(normalize_safe(1e-30d), Is.EqualTo(1d));
        // the arithmetic of the kind of a half is coarse enough to move the result of the scaling of a short value
        Assert.That((float)normalize_safe((Half)0.001f), Is.EqualTo(1f).Within(0.02f));
        Assert.That(rsqrt_a(0.25f), Is.EqualTo(2f).Within(Tolerance));
        Assert.That(normalize_a(2f), Is.EqualTo(1f).Within(Tolerance));
        Assert.That(normalize_safe_a(0f), Is.EqualTo(0f));
        Assert.That(normalize_safe_a(1e-30f), Is.EqualTo(0f));
        Assert.That(normalize_safe_a(2d), Is.EqualTo(1d).Within(DoubleTolerance));
        Assert.That(refract(1f, 1f, 1f), Is.EqualTo(-1f));
        Assert.That(radians(180f), Is.EqualTo(MathF.PI).Within(1e-5f));
        Assert.That(degrees(MathF.PI), Is.EqualTo(180f).Within(1e-3f));

        var fraction = modf(1.25f, out var integral);
        Assert.That(integral, Is.EqualTo(1f));
        Assert.That(fraction, Is.EqualTo(0.25f));

        // the half of a value that is created from a double is converted to the type it is a member of
        Assert.That(min((Half)1, (Half)2), Is.EqualTo((Half)1));
        Assert.That(sqrt((Half)4), Is.EqualTo((Half)2));
        Assert.That((float)radians((Half)180), Is.EqualTo((float)(Half)MathF.PI).Within(0.01f));
    }

    [Test]
    public void Ieee754()
    {
        Assert.That(sqrt(4f), Is.EqualTo(2f));
        Assert.That(rsqrt(0.25f), Is.EqualTo(2f));
        Assert.That(sqrt(4d), Is.EqualTo(2d));
        Assert.That(log(1d), Is.EqualTo(0d));
        Assert.That(log2(8f), Is.EqualTo(3f).Within(1e-5f));
        Assert.That(log10(1000f), Is.EqualTo(3f).Within(1e-5f));
        Assert.That(log(8f, 2f), Is.EqualTo(3f).Within(1e-5f));
        Assert.That(exp(0d), Is.EqualTo(1d));
        Assert.That(exp2(3f), Is.EqualTo(8f).Within(1e-4f));
        Assert.That(exp10(2f), Is.EqualTo(100f).Within(1e-3f));
        Assert.That(pow(2f, 10f), Is.EqualTo(1024f));
        Assert.That(sin(0f), Is.EqualTo(0f));
        Assert.That(cos(0f), Is.EqualTo(1f));
        Assert.That(tan(0f), Is.EqualTo(0f));
        Assert.That(asin(0f), Is.EqualTo(0f));
        Assert.That(acos(1f), Is.EqualTo(0f));
        Assert.That(atan(0f), Is.EqualTo(0f));
        Assert.That(atan2(0f, 1f), Is.EqualTo(0f));
        Assert.That(sinh(0f), Is.EqualTo(0f));
        Assert.That(cosh(0f), Is.EqualTo(1f));
        Assert.That(tanh(0f), Is.EqualTo(0f));
        Assert.That(asinh(0f), Is.EqualTo(0f));
        Assert.That(acosh(1f), Is.EqualTo(0f));
        Assert.That(atanh(0f), Is.EqualTo(0f));

        var (sine, cosine) = sincos(0f);
        Assert.That(sine, Is.EqualTo(0f));
        Assert.That(cosine, Is.EqualTo(1f));
        sincos(0f, out var outSin, out var outCos);
        Assert.That(outSin, Is.EqualTo(0f));
        Assert.That(outCos, Is.EqualTo(1f));

        Assert.That(is_NaN(float.NaN), Is.True);
        Assert.That(is_NaN(0f), Is.False);
        Assert.That(is_finite(0f), Is.True);
        Assert.That(is_finite(float.NaN), Is.False);
        Assert.That(is_inf(float.PositiveInfinity), Is.True);
        Assert.That(is_pos_inf(float.PositiveInfinity), Is.True);
        Assert.That(is_neg_inf(float.PositiveInfinity), Is.False);
        Assert.That(is_neg_inf(double.NegativeInfinity), Is.True);
        // the three names of hlsl are the ones of the members of the library
        Assert.That(isnan(float.NaN), Is.True);
        Assert.That(isfinite(0f), Is.True);
        Assert.That(isinf(float.NegativeInfinity), Is.True);
        Assert.That(is_subnormal(float.Epsilon), Is.True);
        Assert.That(is_subnormal(1f), Is.False);
        Assert.That(is_subnormal(0f), Is.False);
        Assert.That(is_subnormal(double.Epsilon), Is.True);
        Assert.That(is_subnormal(Half.Epsilon), Is.True);

        // the check of a power of two of a floating point value is the one of the framework of the kind of it
        Assert.That(is_pow2(4f), Is.True);
        Assert.That(is_pow2(3f), Is.False);
        Assert.That(is_pow2(0f), Is.False);
        Assert.That(is_pow2(-4f), Is.False);
        Assert.That(is_pow2(float.Epsilon), Is.True);
        Assert.That(up2_pow2(3f), Is.EqualTo(4f));
        Assert.That(up2_pow2(-4f), Is.EqualTo(0f));
        Assert.That(up2_pow2(3d), Is.EqualTo(4d));
        Assert.That(up2_pow2((Half)3f), Is.EqualTo((Half)4f));
    }

    [Test]
    public void Integer()
    {
        Assert.That(is_pow2(8), Is.True);
        Assert.That(is_pow2(0), Is.False);
        Assert.That(is_pow2(-8), Is.False);
        Assert.That(is_pow2(5u), Is.False);
        Assert.That(is_pow2((short)4), Is.True);
        Assert.That(up2_pow2(5u), Is.EqualTo(8u));
        Assert.That(up2_pow2(8ul), Is.EqualTo(8ul));
        Assert.That(up2_pow2(0u), Is.EqualTo(0u));
        // the rounding of a value that has a sign is done in the bits of the unsigned kind of it
        Assert.That(up2_pow2(5), Is.EqualTo(8));
        Assert.That(up2_pow2(-4), Is.EqualTo(0));
        Assert.That(up2_pow2((short)5), Is.EqualTo((short)8));
        Assert.That(up2_pow2(-4L), Is.EqualTo(0L));
    }

    /// <summary>
    /// The select of a value takes a condition instead of a value of its own type, the member that is called on
    /// a value is called on the condition.
    /// </summary>
    [Test]
    public void Select()
    {
        Assert.That(select(true, 1, 2), Is.EqualTo(1));
        Assert.That(select(false, 1, 2), Is.EqualTo(2));
        Assert.That(select(true, 1.5f, 2.5f), Is.EqualTo(1.5f));
        Assert.That(select(false, 1.5, 2.5), Is.EqualTo(2.5));
        Assert.That(select(false, (Half)1, (Half)2), Is.EqualTo((Half)2));
        Assert.That(select(true, 1u, 2u), Is.EqualTo(1u));

        Assert.That(true.select(1, 2), Is.EqualTo(1));
        Assert.That(false.select(1, 2), Is.EqualTo(2));
        Assert.That(false.select(1u, 2u), Is.EqualTo(2u));
        Assert.That(false.select(1.5f, 2.5f), Is.EqualTo(2.5f));
        // the member that is called on the condition is the one every kind of a value reaches, so it takes the
        // kinds that no function of the math class has a member of its own for as well
        Assert.That(false.select(1m, 2m), Is.EqualTo(2m));
        Assert.That(true.select(true, false), Is.True);
        Assert.That(true.select((Half)1, (Half)2), Is.EqualTo((Half)1));
    }

    /// <summary>
    /// The members that are called on a value are the second form of every function of the <c>math</c> class.
    /// </summary>
    [Test]
    public void ValueMembers()
    {
        Assert.That(3.min(5), Is.EqualTo(3));
        Assert.That(3.max(5), Is.EqualTo(5));
        Assert.That(7.clamp(1, 5), Is.EqualTo(5));
        Assert.That((-4).abs(), Is.EqualTo(4));
        Assert.That(3.square(), Is.EqualTo(9));
        Assert.That(3.dot(4), Is.EqualTo(12));
        Assert.That(5.unlerp(0, 10), Is.EqualTo(0));
        Assert.That(3.remap(0, 3, 0, 9), Is.EqualTo(9));
        Assert.That(4f.sqrt(), Is.EqualTo(2f));
        Assert.That(1.25f.frac(), Is.EqualTo(0.25f));
        // the value that the interpolation is called on is the factor
        Assert.That(0.5.lerp(0.0, 10.0), Is.EqualTo(5.0));
        Assert.That(2f.pow(10f), Is.EqualTo(1024f));
        Assert.That(8f.log(2f), Is.EqualTo(3f).Within(1e-5f));
        Assert.That(3f.atan2(1f), Is.EqualTo(MathF.Atan2(3f, 1f)));
        Assert.That(3f.step(2f), Is.EqualTo(1f));
        Assert.That(0.5f.smoothstep(0f, 1f), Is.EqualTo(0.5f));
        Assert.That(8f.is_finite(), Is.True);
        Assert.That(float.NaN.is_NaN(), Is.True);
        Assert.That(5u.up2_pow2(), Is.EqualTo(8u));
        Assert.That((-4).up2_pow2(), Is.EqualTo(0));
        Assert.That(8.is_pow2(), Is.True);
        Assert.That(3f.is_pow2(), Is.False);
        Assert.That(3f.up2_pow2(), Is.EqualTo(4f));

        var fraction = 1.25f.modf(out var integral);
        Assert.That(integral, Is.EqualTo(1f));
        Assert.That(fraction, Is.EqualTo(0.25f));

        0f.sincos(out var outSin, out var outCos);
        Assert.That(outSin, Is.EqualTo(0f));
        Assert.That(outCos, Is.EqualTo(1f));
        var (sin, cos) = 0f.sincos();
        Assert.That(sin, Is.EqualTo(0f));
        Assert.That(cos, Is.EqualTo(1f));
    }
}
